CLASS zcl_abapedit_code_gen DEFINITION PUBLIC FINAL CREATE PUBLIC.
  PUBLIC SECTION.
    METHODS generate_simple_report
      IMPORTING
        iv_message TYPE string OPTIONAL
      RETURNING
        VALUE(rv_abap_code) TYPE string.
ENDCLASS.

CLASS zcl_abapedit_code_gen IMPLEMENTATION.
  METHOD generate_simple_report.
    DATA(lv_message) = COND string( WHEN iv_message IS SUPPLIED AND iv_message IS NOT INITIAL THEN iv_message ELSE 'Hello from generated ABAP!' ).

    rv_abap_code = |REPORT Z_GENERATED_REPORT.{ |\n|}
                   |WRITE: / '{ lv_message }'.{ |\n|}
                   |ULINE.{ |\n|}
                   |WRITE: / 'Current Date: { sy-datum }'.{ |\n|}
                   |WRITE: / 'Current Time: { sy-uzeit }'.{ |\n|}
                   |.{ |\n|}
                   |START-OF-SELECTION.{ |\n|}
                   |  " No specific logic here, just output.{ |\n|}
                   |END-OF-SELECTION.{ |\n|}.
  ENDMETHOD.
ENDCLASS.
